
const tasks=[['bag','自己整理书包','看看课表，把明天要用的装好','整理小达人'],['book','自己开始学习','到约好的时间，自己开始','自主学习者'],['clock','按计划完成','照着自己安排的顺序做','时间魔法师'],['star','做完自己检查','做完以后，再看一遍','检查小侦探'],['ball','自己收好玩具','玩完了，让玩具回家','物品管理师'],['heart','到点结束娱乐','约好的时间到了，自己停下来','约定守护者']];
const rewards=[['📖','故事我来选','选一本今晚想读的故事',5],['🎲','家庭游戏我来选','和家人约好一起玩的游戏',8],['🍜','晚饭我来选','从家长给出的三样中选择',10],['🌳','周末去哪里','一起选一次户外活动',15],['🎬','家庭电影之夜','从合适的影片里选一部',12],['🧭','专属活动我来定','和爸爸或妈妈一起安排',15]];
const dayKey=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const blank=()=>({days:{},stars:0,counts:[0,0,0,0,0,0],rewards:[],name:'小小探险家',goal:3,graduated:[],prices:rewards.map(x=>x[3])});let s;try{s=JSON.parse(localStorage.getItem('self-growth-v1'))||blank()}catch{s=blank()}let page='today',picks=[],parentOpen=false,toastTimer;const $=id=>document.getElementById(id);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function today(){return s.days[dayKey()]??=( {selected:[],done:{},plan:['吃点心','玩20分钟','学习时间','自由时间','整理书包'],planned:false,mood:null,note:''})}function save(){try{localStorage.setItem('self-growth-v1',JSON.stringify(s))}catch{toast('未能保存，请检查浏览器存储空间')}}function toast(t){$('notice').innerHTML='<div class="toast">'+esc(t)+'</div>';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').innerHTML='',2600)}function art(k){return '<span aria-hidden="true" class="art '+k+'"></span>'}function show(html){$('modal').innerHTML='<button class="close" aria-label="关闭" onclick="closeModal()">×</button>'+html;if(!$('modal').open)$('modal').showModal()}function closeModal(){$('modal').close()}function go(p){page=p;render();window.scrollTo(0,0)}
const mascot = (cls='mascot') => `<img class="${cls}" src="star-friend.png" alt="" decoding="async">`;
const wallet = () => `<span class="balance" aria-label="${s.stars}颗星星">${mascot('wallet-star')} ${s.stars}<small>颗星星</small></span>`;
const heading = (tag,title,desc) => `<div class="page-heading"><div><p class="eyebrow">${tag}</p><h1>${title}</h1><p class="sub">${desc}</p></div>${mascot()}</div>`;
const sticker = k => `<span class="sticker">${art(k)}</span>`;
const taskLabel = ['整理小达人','自主学习者','时间魔法师','检查小侦探','物品管理师','约定守护者'];
function render() {
  const d=today(), n=Object.keys(d.done).length;
  const tabs=[['today','☀️','今天'],['plan','🎒','我的一天'],['growth','🌱','成长'],['rewards','🎁','奖励屋']];
  $('nav').innerHTML=tabs.map(([id,icon,label])=>`<button class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} onclick="go('${id}')"><span class="navicon" aria-hidden="true">${icon}</span>${label}</button>`).join('')+`<div class="navfriend">${mascot()}<p>我是小星星，<br>陪你练习自己做主！</p></div>`;
  let html='';
  if(page==='today'){
    html=`<div class="row"><p class="eyebrow">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</p>${wallet()}</div>
    <section class="story-hero"><img class="scene" src="storybook-scene.png" alt="小星星和小兔背着书包，在开满花的小路上出发" fetchpriority="high"><div class="story-copy"><span class="story-tag">✦ 小小成长，大大本领</span><h1>今天，<br>我来做主！</h1><p>你好，${esc(s.name)}<br>和小星星一起，试试自己来。</p></div></section>
    <div class="row sectionhead"><h2><span class="sectionicon" aria-hidden="true">🎯</span>我的小挑战 <span class="count">${n} / ${d.selected.length}</span></h2><button class="link" onclick="choose()">${d.selected.length?'换一换':'自己选挑战'}</button></div>`;
    if(d.selected.length){
      html+=`<div class="cards">${d.selected.map((i,pos)=>`<article class="task ${d.done[i]?'done':''}">${sticker(tasks[i][0])}<div class="copy"><div class="task-kicker">挑战 ${String(pos+1).padStart(2,'0')} · ${taskLabel[i]}</div><h3>${tasks[i][1]}</h3><div class="sub">${d.done[i]?(d.done[i]==='self'?'自己想起来的 · 收获 1 颗星':'提醒后完成 · 今天也有练习'):tasks[i][2]}</div></div><button class="donebutton" aria-label="完成${tasks[i][1]}" ${d.done[i]?'disabled':''} onclick="complete(${i})"><span aria-hidden="true">${d.done[i]?'✓':'+'}</span><small>${d.done[i]?'完成啦':'我做完了'}</small></button></article>`).join('')}</div>`;
    }else{
      html+=`<div class="empty-challenges"><div class="sticker-trio" aria-hidden="true">${['bag','book','clock'].map(sticker).join('')}</div><h3>今天，想试试哪件事？</h3><p class="sub">从 1 个小挑战开始，最多选 3 个。</p><button class="primary gold" onclick="choose()">✦ 挑选我的小挑战</button></div>`;
    }
    html+=`<button class="plan-link" onclick="go('plan')"><span class="plan-mini" aria-hidden="true">🗓️</span><span class="copy"><strong>${d.planned?'我的一天，安排好啦':'我的一天，我来安排'}</strong><span class="sub">${d.planned?'点开看看今天的小计划':'先学习还是先玩？你来排一排'}</span></span><span aria-hidden="true">→</span></button>
    <div class="mood-panel"><div class="row sectionhead"><h2>今天的心情颜色</h2><span class="sub">想说就说</span></div><div class="moods">${['😄','🙂','😐','🙁','😴'].map((x,i)=>`<button class="${d.mood===i?'chosen':''}" aria-label="${['开心','不错','一般','有点烦','好累'][i]}" aria-pressed="${d.mood===i}" onclick="mood(${i})"><span style="font-size:inherit;line-height:1.2" aria-hidden="true">${x}</span><span>${['开心','不错','一般','有点烦','好累'][i]}</span></button>`).join('')}</div></div>
    ${d.note?`<div class="note"><h3>💌 给你的一句话</h3><p>${esc(d.note)}</p></div>`:''}<p class="footnote">每天一点点，慢慢来就很好。</p>`;
  }
  if(page==='plan'){
    const emojis={'吃点心':'🍎','玩20分钟':'⚽','学习时间':'📚','自由时间':'🪁','整理书包':'🎒'};
    html=heading('我的小小时间魔法','我的一天','先做什么？后做什么？')+`<div class="tip"><span aria-hidden="true">💡</span><span>点上下箭头换顺序，再和家长约好时间。</span></div><div class="planbook"><div class="pill">🏡 放学回家啦</div><div class="plan-path">${d.plan.map((x,i)=>`<div class="planrow"><span class="number">${i+1}</span><span class="plan-emoji" aria-hidden="true">${emojis[x]||'🌈'}</span><strong>${esc(x)}</strong><button class="move" aria-label="上移${esc(x)}" ${!i?'disabled':''} onclick="move(${i},-1)">↑</button><button class="move" aria-label="下移${esc(x)}" ${i===d.plan.length-1?'disabled':''} onclick="move(${i},1)">↓</button></div>`).join('')}</div><div class="pill">🌙 洗漱 · 睡觉</div></div><button class="primary gold" onclick="today().planned=true;save();toast('安排好了，去试试看！');go('today')">✓ 就这样安排！</button><p class="footnote">计划可以一起调整，睡觉时间要留够。</p>`;
  }
  if(page==='growth'){
    html=heading('我的成长徽章册','我正在长本领','星星花掉，本领还在。')+`<div class="tip"><span aria-hidden="true">🌱</span><span>自主完成 ${s.goal} 次，就有第一枚徽章。<br>不用连续，休息一天也没关系。</span></div><div class="grid skill-grid">${tasks.map((t,i)=>{
      const c=s.counts[i],lv=Math.min(3,Math.floor(c/s.goal));
      const nextTarget=Math.min(3,lv+1)*s.goal;
      return `<article class="tile"><div class="skill-badge">${art(t[0])}<span class="badge-level">${s.graduated.includes(i)?'已毕业':lv?'Lv. '+lv:'小小新芽'}</span></div><h3>${t[3]}</h3><span class="pill">${s.graduated.includes(i)?'学会啦 · 继续保持':lv?['','初次解锁','越来越熟练','稳定练习'][lv]:'正在练习中'}</span><div class="skill-stars" aria-label="已获得${lv}级徽章">${Array.from({length:3},(_,j)=>`<span class="${j>=lv?'unearned':''}" aria-hidden="true">${j<lv?'★':'☆'}</span>`).join('')}</div><div class="progress" role="progressbar" aria-label="${t[3]}三级进度" aria-valuemin="0" aria-valuemax="${s.goal*3}" aria-valuenow="${Math.min(c,s.goal*3)}"><span style="width:${Math.min(c/(s.goal*3)*100,100)}%"></span></div><p class="sub">自主完成 ${c} 次${lv<3?` · 再练 ${nextTarget-c} 次升级`:''}</p></article>`;
    }).join('')}</div><button class="primary" onclick="weekly()">📖 一起翻翻这一周</button><p class="footnote">真正学会了，再和家长一起毕业。</p>`;
  }
  if(page==='rewards'){
    const categories=['故事时光','一起玩耍','美味选择','周末探险','家庭时光','专属约定'];
    html=`<div class="row"><p class="eyebrow">我的小小选择权</p>${wallet()}</div><h1 style="margin-top:20px">欢迎来到奖励屋</h1><div class="reward-banner"><span class="rewardicon" aria-hidden="true">🎁</span><div><h3>把星星，变成好时光</h3><p class="sub">先和家长约好，再选一张喜欢的奖励券。</p></div></div><div class="grid reward-grid">${rewards.map((r,i)=>`<article class="tile"><div class="reward-top"><div class="rewardicon" aria-hidden="true">${r[0]}</div><div class="reward-category">${categories[i]}</div></div><div class="reward-body"><h3>${r[1]}</h3><p class="sub">${r[2]}</p><button class="primary gold" ${s.stars<s.prices[i]?'disabled':''} onclick="redeem(${i})">${s.stars<s.prices[i]?'还差 '+(s.prices[i]-s.stars)+' 颗星':'⭐ '+s.prices[i]+' 颗 · 兑换'}</button></div></article>`).join('')}</div><h2 class="sectionhead">🎟️ 我的奖励券</h2>${s.rewards.length?s.rewards.slice().reverse().map(r=>`<div class="receipt">${rewards[r.id][0]} <strong>${rewards[r.id][1]}</strong><div class="sub">${r.date} · ${r.used?'已一起享受':'已兑换，等家长安排'}</div></div>`).join(''):`<div class="empty-coupons"><span class="rewardicon" aria-hidden="true">🎟️</span><p class="sub">第一张奖励券，会在这里等你。</p></div>`}`;
  }
  $('main').innerHTML=html;
}
function celebrate(type){
  clearTimeout(toastTimer);
  const title=type==='self'?'我看到你的主动啦！':'今天也有小进步！';
  const description=type==='self'?'收好这颗星星，本领也长大一点。':'完成了一次练习，下次再试试。';
  const colors=['#ffc83d','#5db9e3','#ff9fbc','#80ba72','#b99ee1'];
  const confetti=Array.from({length:18},(_,i)=>`<i style="--confetti-color:${colors[i%5]};--dx:${Math.cos(i*2.4)*(80+i*9)}px;--dy:${Math.sin(i*2.4)*(75+i*8)+100}px;--spin:${i*53}deg"></i>`).join('');
  $('notice').innerHTML=`<div class="confetti" aria-hidden="true">${confetti}</div><div class="toast celebration">${mascot()}<div><strong>${title}</strong><small>${description}</small></div></div>`;
  toastTimer=setTimeout(()=>$('notice').innerHTML='',3000);
}

function choose(){picks=[...today().selected];drawChoices()}function drawChoices(){show('<h2>今天想练哪几项？</h2><p class="sub">选 1–3 项。完成过的挑战会保留。</p>'+tasks.map((t,i)=>s.graduated.includes(i)&&!today().selected.includes(i)?'':'<button class="choice task-choice '+(picks.includes(i)?'selected':'')+'" aria-pressed="'+picks.includes(i)+'" onclick="pick('+i+')">'+art(t[0])+t[1]+'<span class="choice-check" aria-hidden="true">'+(picks.includes(i)?'✓':'＋')+'</span></button>').join('')+'<button class="primary" '+(!picks.length?'disabled':'')+' onclick="today().selected=[...picks];save();closeModal();render()">选好了（'+picks.length+'/3）</button>')}function pick(i){if(today().done[i])return toast('今天已经完成啦，明天再换');if(picks.includes(i))picks=picks.filter(x=>x!==i);else if(picks.length<3)picks.push(i);else return toast('每天最多 3 项，先取消一项吧');drawChoices()}
function complete(i){
  if(today().done[i]||!today().selected.includes(i))return;
  show(mascot('completion-art')+`<h2>${tasks[i][1]}</h2><p>这次是怎样开始的？</p><button class="choice self-choice" onclick="finish(${i},'self')"><span class="choice-title"><span class="choice-emoji" aria-hidden="true">⭐</span>我自己想起来的</span><span class="sub">记录自主完成，得到 1 颗星</span></button><button class="choice help-choice" onclick="finish(${i},'help')"><span class="choice-title"><span class="choice-emoji" aria-hidden="true">🌱</span>有人提醒我</span><span class="sub">记录这次练习，不扣星星</span></button><p class="sub">诚实记录，下次再试试自己想起来。</p>`);
}
function finish(i,type){if(today().done[i]||!today().selected.includes(i)||!['self','help'].includes(type))return;today().done[i]=type;if(type==='self'){s.stars++;s.counts[i]++}save();closeModal();render();celebrate(type)}
function move(i,k){let d=today();if(i+k<0||i+k>=d.plan.length)return;[d.plan[i],d.plan[i+k]]=[d.plan[i+k],d.plan[i]];d.planned=false;save();render()}function mood(i){today().mood=i;save();render()}function redeem(i){if(s.stars<s.prices[i])return;show('<h2>'+rewards[i][1]+'</h2><p>使用 '+s.prices[i]+' 颗星星，换一张奖励券。</p><p class="sub">和家长一起约好兑现时间，成长进度不会减少。</p><button class="primary" onclick="confirmReward('+i+')">确定兑换</button>')}function confirmReward(i){if(s.stars<s.prices[i])return; s.stars-=s.prices[i];s.rewards.push({id:i,date:dayKey(),used:false});save();closeModal();render();toast('奖励券收好啦！')}
function recent(){return Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return [key,s.days[key]]})}function weekly(){let rows=recent(),a=0,b=0;rows.forEach(([,d])=>Object.values(d?.done||{}).forEach(t=>t==='self'?a++:b++));show('<h2>这一周的小发现</h2><p class="sub">最近 7 天 · 只统计已记录的挑战</p><div class="grid"><div class="tile"><div class="metric">'+a+'</div><div class="sub">自主完成</div></div><div class="tile"><div class="metric">'+b+'</div><div class="sub">提醒后完成</div></div></div><div class="guide"><table><tr><th>日期</th><th>自己想起 / 提醒后</th></tr>'+rows.map(([k,d])=>'<tr><td>'+k.slice(5)+'</td><td>'+(d&&Object.keys(d.done).length?Object.values(d.done).filter(x=>x==='self').length+' / '+Object.values(d.done).filter(x=>x==='help').length:'未记录')+'</td></tr>').join('')+'</table></div><p>哪件事越来越熟练了？<br>明天想让哪件事更容易一点？</p><p class="sub">“提醒后完成”是任务次数，不是催促次数。未记录的日子不算失败。</p>')}
$('parent').onclick=()=>{parentOpen=false;show('<h2>请家长来帮忙</h2><p class="sub">请按顺序输入“一二三四”的数字形式，进入家长区。</p><label>家长确认<input id="gate" inputmode="numeric" type="password" maxlength="4" autocomplete="off"></label><button class="primary" onclick="if($(\'gate\').value===\'1234\'){parentOpen=true;parents()}else toast(\'请让家长输入 1234\')">进入</button><p class="sub">这是防误触入口。</p>')};function parents(){if(!parentOpen)return;show('<h2>家长小帮手</h2><label>孩子的昵称<input id="name" maxlength="12" value="'+esc(s.name)+'"></label><label>每级需要自主完成的次数<select id="goal">'+[3,5,7].map(v=>'<option '+(s.goal===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>今天的一句具体鼓励<input id="note" maxlength="80" value="'+esc(today().note)+'" placeholder="今天你自己想起了整理书包，我看到了"></label><button class="primary" onclick="saveParent()">保存设置</button><details><summary>调整兑换星星</summary>'+rewards.map((r,i)=>'<label>'+r[1]+'<input id="price'+i+'" type="number" min="1" max="99" value="'+s.prices[i]+'"></label>').join('')+'<button class="secondary" onclick="savePrices()">保存兑换规则</button></details><details><summary>奖励兑现</summary>'+(s.rewards.map((r,i)=>'<div class="receipt">'+rewards[r.id][1]+' · '+(r.used?'已兑现':'<button class="link" onclick="s.rewards['+i+'].used=true;save();parents()">确认已兑现</button>')+'</div>').join('')||'<p class="sub">还没有兑换记录。</p>')+'</details><details><summary>技能毕业</summary><p class="sub">稳定两三周后一起商量。毕业任务不再进入新挑战；历史成长保留。</p>'+tasks.map((t,i)=>'<div class="receipt">'+t[3]+'<button class="link" onclick="graduate('+i+')">'+(s.graduated.includes(i)?'恢复练习':'一起毕业')+'</button></div>').join('')+'</details><button class="link" onclick="guide()">使用说明与四页设计逻辑</button><p class="sub">记录只保存在当前浏览器，不会跨设备同步。清理浏览器数据会丢失记录。</p>')}
function saveParent(){if(!parentOpen)return;s.name=$('name').value.trim()||'小小探险家';s.goal=Number($('goal').value);today().note=$('note').value.trim();save();closeModal();render();toast('设置已保存')}function savePrices(){if(!parentOpen)return;let p=rewards.map((_,i)=>Number($('price'+i).value));if(p.some(x=>!Number.isInteger(x)||x<1||x>99))return toast('星星数请填 1–99 的整数');s.prices=p;save();toast('兑换规则已保存');render()}function graduate(i){if(!parentOpen)return;if(s.graduated.includes(i))s.graduated=s.graduated.filter(x=>x!==i);else s.graduated.push(i);save();parents();render()}
function guide(){show('<h2>每天三分钟，一起试试看</h2><div class="guide"><ol><li><b>放学后：</b>孩子自己选 1–3 个挑战，在“我的一天”用上下箭头排顺序，与家长一起约定。</li><li><b>完成后：</b>点挑战右边的“我做完了”，记录是自己想起来的，还是提醒后完成的。自主完成得 1 星，每项每天仅记一次。</li><li><b>积累后：</b>在奖励屋兑换选择权，再由家长安排兑现。兑换不减少能力成长。</li><li><b>睡前：</b>可选一个心情，家长写一句具体鼓励。</li><li><b>周末：</b>在成长页查看最近 7 天，一起想想哪件事需要更少提醒。</li></ol><h3>四页信息架构</h3><table><tr><th>页面</th><th>主要操作</th></tr><tr><td>今天</td><td>选挑战 → 完成记录 → 即时反馈</td></tr><tr><td>我的一天</td><td>调整顺序 → 确认安排</td></tr><tr><td>成长</td><td>查看累计能力 → 一周回顾</td></tr><tr><td>奖励屋</td><td>查看余额 → 兑换 → 待兑现券</td></tr></table><p>家长入口：昵称、鼓励、升级次数、兑换规则、兑现与技能毕业。入口数字为 1234，仅防误触。</p><h3>一起约定</h3><p>奖励主动，不评价题目对错；不扣已经挣到的星星；不要求连续打卡；徽章代表练习积累，毕业由实际表现决定。亲子陪伴和基本关爱始终都有。</p><h3>这一版的范围</h3><p>这是可操作的手机网页原型，包含 6 个预设能力与 6 个奖励。没有账户同步、自定义任务或设备时间锁。每天按设备本地日期更新，记录留在当前浏览器。</p><p>视觉采用绘本风格的小星星伙伴，搭配原成长板的书包、闹钟和图书插图。任务完成时会有短暂庆祝；系统设置减少动态效果时，页面也会减少动画。</p></div>')}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});render();
